/** @file dendriteramp.h
 @brief A brief, one sentence description.

 A more detailed multiline description...

 @author Peter Drysdale, Felix Fung,
 */

#ifndef NFTSIM_SRC_DENDRITESCALED_H
#define NFTSIM_SRC_DENDRITESCALED_H

// Other nftsim headers
#include "configf.h"    // Configf;
#include "coupling.h"   // Coupling;
#include "de.h"         // DE; RK4;
#include "dendrite.h"   // Dendrite;
#include "output.h"     // Output;
#include "propagator.h" // Propagator;

// C++ standard library headers
#include <vector> // std::vector;
using std::vector;

class DendriteScaled : public Dendrite {
    double factorab = 0.0;   ///< == 1./alpha + 1./beta;
    double alphaxbeta = 0.0; ///< == alpha * beta;
    double tpk = 0.0;
    double eta = 0.0;
    double h_fac = 0.0;
    double hsyn = 0.0;
protected:
    struct DendriteDE : public DE {
        double factorab = 0.0, alphaxbeta = 0.0;
        double tpk = 0.0, eta = 0.0;
        double h_fac = 0.0, hsyn = 0.0;;
        virtual void init(double vinit);
        DendriteDE( size_type nodes, double deltat) : DE(nodes, deltat, 3) {}
        ~DendriteDE() override = default;
        void rhs( const std::vector<double>& y, std::vector<double>& dydt, size_type /*unused*/ ) override;
    };
    DendriteDE* de; //Must redeclare here otherwise we get Dendrite::DendriteDE.
    RK4* rk4;       //Must redeclare here otherwise we get seg-fault

    double alpha = 0.0; ///< Mean decay rate of the soma response to a delta-function synaptic input (needed here for DendriteRamp).
    double beta = 0.0; ///< Mean rise rate of the soma response to a delta-function synaptic input.


    void init( Configf& configf ) override;
public:
    DendriteScaled() = delete;                    // No default constructor allowed.
    DendriteScaled(const DendriteScaled&) = delete; // No copy constructor allowed.

    DendriteScaled( size_type nodes, double deltat, size_type index,
                 const Propagator& prepropag, const Coupling& precouple );
    ~DendriteScaled() override;
    //void step() override;

    inline const std::vector<double>& V() const {
        return (*de)[0]; //NOTE: Pretty sure this is an error: index=1 points to dv/dt, to get voltage, which is what I think is wanted here, it should be index=0
    }
    void output( Output& output ) const override;
};

#endif //NFTSIM_SRC_DENDRITESCALED_H

