/** @file dendrite_scaled.cpp
 @brief Defines the Dendrite class, which handles Hindriks-van Putten dendritic dynamics.

 Dendrite dynamics are applied to incoming activity to postsynaptic Population
 objects. The differential equation defining the dendritic dynamics are in the
 member function Dendrite::DendriteDE::rhs.

 @author Eli Muller,
 */

// Main module header
#include "dendrite_scaled.h"   // DendriteScaled;

// Other nftsim headers
#include "configf.h"    // Configf;
#include "coupling.h"   // Coupling;
#include "de.h"         // RK4;
#include "output.h"     // Output;
#include "propagator.h" // Propagator;

// C++ standard library headers
#include <string>   // std::string;
#include <vector>   // std::vector;
#include <cmath>     // std::exp;
using std::string;
using std::vector;

/**
 @brief Computes the derivatives of the dendritic response function.

 The dendritic response function is given by:
 \f{eqnarray*}{
 \frac{dv}{dt}&=&W \\
 \frac{dW}{dt}&=&\left(\nu\phi - V - \left(\frac{1}{\alpha} + \frac{1}{\beta}\right) W\right) \alpha \beta \\
 \frac{d\nu\phi}{dt}&=&0
 \f}
 */
void DendriteScaled::DendriteDE::rhs( const vector<double>& y, vector<double>& dydt, size_type /*unused*/ ) {
    // y = {V,W==dv/dt,nuphi}
    // dydt = {dv/dt==W, dW/dt==d^2V/dt^2,dnuphi/dt}  d(nuphi)/dt from precouple
    dydt[0] = y[1];

    dydt[1] = (h_fac*y[2] - y[0] - factorab * y[1]) * alphaxbeta;

    dydt[2] = 0.0;
}

void DendriteScaled::init( Configf& configf ) {
    Dendrite::init(configf);

    //configf.param("alpha",alpha);
    //configf.param("beta",beta);
    configf.param("hsyn",hsyn);

    tpk = log(beta/alpha)/(beta - alpha);
    eta = (alpha*beta)*(exp(-alpha*tpk) - exp(-beta*tpk))/(beta - alpha);
    h_fac = hsyn/eta;


    // Initialize constant factors to speed up computation.
    factorab = 1./alpha + 1./beta;
    alphaxbeta = alpha * beta;

    de->init(v[0]); // call Dendrite::DendriteDE::init
    de->factorab = factorab;
    de->alphaxbeta = alphaxbeta;
    de->h_fac = h_fac;
}

void DendriteScaled::DendriteDE::init(const double vinit) {
    variables[0].clear();
    variables[1].clear();
    variables[2].clear();
    variables[0].resize(nodes, vinit);
    variables[1].resize(nodes, 0.0);
    variables[2].resize(nodes, 0.0);
}

DendriteScaled::DendriteScaled( size_type nodes, double deltat, size_type index,
                           const Propagator& prepropag, const Coupling& precouple )
: Dendrite(nodes,deltat,index,prepropag,precouple)

{
    de = new DendriteDE(nodes, deltat);
    rk4 = new RK4(*de);
}

DendriteScaled::~DendriteScaled() {
    delete de;
    delete rk4;
}

void DendriteScaled::output( Output& output ) const {
    output("Dendrite",index+1,"V",v);
}

